{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Pamatolol, a close aryloxypropanolamine beta-blocker analogue, showed absolute oral bioavailability values of 64.9–103.5% in healthy subjects, directly supporting high F for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Pindolol, another aryloxypropanolamine beta-blocker, had an absolute oral bioavailability of 86 ± 7% versus IV in patients without renal impairment, indicating high oral absorption and low first-pass loss.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Diacetolol, a structurally related beta-blocker, had a mean oral bioavailability of 0.426 ± 0.068 at an 800 mg dose, still well above the 20% threshold despite incomplete absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Bufuralol, a lipophilic beta-blocker analogue, showed fractional systemic availability of 0.77 in a healthy volunteer, supporting high oral bioavailability in this compound family.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is talinolol, an aryloxypropanolamine beta-blocker. All highly transferable analogues (pamatolol, pindolol, diacetolol, bufuralol) show absolute oral bioavailability well above 20%, typically 30–100%. Rifampin co-treatment may reduce exposure through P-gp/CYP induction, but the strong class-level evidence supports F remaining ≥20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for talinolol under rifampin co-treatment is present in the supplied evidence.",
    "All retrieved evidence comes from related molecules without rifampin co-treatment; the rifampin effect is inferred rather than directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

